const sumBilledSegmentsSince = `-- name: SumBilledSegmentsSince :one
SELECT COALESCE(sum(billed_segments), 0)::bigint AS n
FROM sms_messages
WHERE direction = 'outbound'
  AND billed_segments IS NOT NULL
  AND created_at >= $1
`

func (q *Queries) SumBilledSegmentsSince(ctx context.Context, since time.Time) (int64, error) {
	row := q.db.QueryRow(ctx, sumBilledSegmentsSince, since)
	var n int64
	err := row.Scan(&n)
	return n, err
}

const sumDebitsSince = `-- name: SumDebitsSince :one
SELECT COALESCE(sum(amount), 0)::billing_money AS spent
FROM wallet_transactions
WHERE type = 'DEBIT'
  AND created_at >= $1
`

