const sumWalletBalances = `-- name: SumWalletBalances :one
SELECT
    COALESCE(sum(available_balance), 0)::billing_money AS available_total,
    COALESCE(sum(held_balance), 0)::billing_money AS held_total
FROM wallets w
JOIN clients c ON c.id = w.client_id AND c.status = 'active'
`

type SumWalletBalancesRow struct {
	AvailableTotal decimal.Decimal `json:"available_total"`
	HeldTotal      decimal.Decimal `json:"held_total"`
}

func (q *Queries) SumWalletBalances(ctx context.Context) (SumWalletBalancesRow, error) {
	row := q.db.QueryRow(ctx, sumWalletBalances)
	var i SumWalletBalancesRow
	err := row.Scan(&i.AvailableTotal, &i.HeldTotal)
	return i, err
}

