const upsertClientTariff = `-- name: UpsertClientTariff :one
INSERT INTO client_tariffs (client_id, product, tariff_plan_id, price_override, effective_from, effective_to)
VALUES (
    $1, $2, $3,
    $4, now(), $5
)
ON CONFLICT (client_id, product) DO UPDATE SET
    tariff_plan_id = EXCLUDED.tariff_plan_id,
    price_override = EXCLUDED.price_override,
    effective_from = now(),
    effective_to = EXCLUDED.effective_to,
    updated_at = now()
RETURNING id, client_id, product, tariff_plan_id, price_override, effective_from, effective_to, created_at, updated_at
`

type UpsertClientTariffParams struct {
	ClientID      uuid.UUID        `json:"client_id"`
	Product       BillingProduct   `json:"product"`
	TariffPlanID  uuid.UUID        `json:"tariff_plan_id"`
	PriceOverride *decimal.Decimal `json:"price_override"`
	EffectiveTo   *time.Time       `json:"effective_to"`
}

func (q *Queries) UpsertClientTariff(ctx context.Context, arg UpsertClientTariffParams) (ClientTariff, error) {
	row := q.db.QueryRow(ctx, upsertClientTariff,
		arg.ClientID,
		arg.Product,
		arg.TariffPlanID,
		arg.PriceOverride,
		arg.EffectiveTo,
	)
	var i ClientTariff
	err := row.Scan(
		&i.ID,
		&i.ClientID,
		&i.Product,
		&i.TariffPlanID,
		&i.PriceOverride,
		&i.EffectiveFrom,
		&i.EffectiveTo,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
